def split_bill(total_cents: int, weights: list[int]) -> list[int]:
    for w in weights:
        if w < 0:
            raise ValueError
    if not weights:
        return []

    total_weight = sum(weights)
    if total_weight == 0:
        raise ValueError

    n = len(weights)
    shares = [(total_cents * w) // total_weight for w in weights]
    remainder = total_cents - sum(shares)

    if remainder > 0:
        order = sorted(
            range(n),
            key=lambda i: (-((total_cents * weights[i]) % total_weight), i),
        )
        for i in order[:remainder]:
            shares[i] += 1

    return shares
```

