from itertools import zip_longest

def compare_versions(a: str, b: str) -> int:
    def parse(version: str):
        if version and version[0] in ('v', 'V'):
            version = version[1:]

        if '-' in version:
            main, pre = version.split('-', 1)
        else:
            main, pre = version, None

        parts = tuple(int(x) for x in main.split('.')) if main else ()
        return parts, pre

    a_parts, a_pre = parse(a)
    b_parts, b_pre = parse(b)

    for x, y in zip_longest(a_parts, b_parts, fillvalue=0):
        if x != y:
            return 1 if x > y else -1

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    if a_pre < b_pre:
        return -1
    if a_pre > b_pre:
        return 1
    return 0
